"use client"; import Link from "next/link"; import { usePathname, useRouter } from "next/navigation"; import { useState } from "react"; import { LayoutDashboard, FolderOpen, FileText, Briefcase, BookOpen, FileUser, Globe, Sparkles, Settings, Inbox, Menu, X, LogOut } from "lucide-react"; import { useAuth } from "./AuthProvider"; import { supabase } from "@/lib/supabase"; import { cn } from "@/lib/utils";
const NAV=[{href:"/app/dashboard",label:"Dashboard",icon:LayoutDashboard},{href:"/app/workspaces",label:"Research",icon:BookOpen},{href:"/app/documents",label:"Documents",icon:FileText},{href:"/app/projects",label:"Projects",icon:Briefcase},{href:"/app/career",label:"Career Hub",icon:FolderOpen},{href:"/app/resume",label:"Resume Builder",icon:FileUser},{href:"/app/portfolio",label:"Portfolio",icon:Globe},{href:"/app/career-ai",label:"Career AI",icon:Sparkles}];
export function AppShell({children}:{children:React.ReactNode}){const path=usePathname();const router=useRouter();const {user,loading}=useAuth();const [open,setOpen]=useState(false);const isAdmin=(user?.app_metadata as {role?:string}|undefined)?.role==="admin";
if(loading) return <div className="flex min-h-screen items-center justify-center bg-[#050807]"><div className="h-8 w-56 animate-pulse rounded-md bg-zinc-800"/></div>;
if(!user){ if(typeof window!=="undefined") router.replace("/login"); return null; }
const sidebar=<div className="flex h-full flex-col"><div className="flex h-16 items-center gap-2 border-b border-white/[0.06] px-5"><span className="flex h-8 w-8 items-center justify-center rounded-md bg-emerald-400 font-display text-sm font-bold text-zinc-950">Z</span><span className="font-display font-semibold tracking-tight">ZEVQYN</span></div><nav className="flex-1 space-y-1 overflow-y-auto px-3 py-4">{NAV.map(i=>{const active=path===i.href||path.startsWith(i.href+"/");return <Link key={i.href} href={i.href} onClick={()=>setOpen(false)} className={cn("flex items-center gap-3 rounded-md px-3 py-2 text-sm",active?"bg-indigo-600/15 text-indigo-200":"text-zinc-400 hover:bg-white/5 hover:text-zinc-100")}><i.icon className="h-4 w-4"/>{i.label}</Link>;})}{isAdmin&&<Link href="/app/admin/inbox" className="flex items-center gap-3 rounded-md px-3 py-2 text-sm text-zinc-400 hover:bg-white/5"><Inbox className="h-4 w-4"/>Admin Inbox</Link>}<Link href="/app/settings" className="flex items-center gap-3 rounded-md px-3 py-2 text-sm text-zinc-400 hover:bg-white/5"><Settings className="h-4 w-4"/>Settings</Link></nav><div className="border-t border-white/[0.06] p-3"><p className="truncate px-2 text-xs text-zinc-500">{user.email}</p><button onClick={async()=>{await supabase.auth.signOut();router.replace("/login");}} className="mt-2 flex w-full items-center gap-2 rounded-md px-3 py-2 text-sm text-zinc-300 hover:bg-white/5"><LogOut className="h-4 w-4"/>Sign out</button></div></div>;
return <div className="min-h-screen bg-[#050807] text-zinc-100"><aside className="fixed inset-y-0 left-0 z-40 hidden w-64 border-r border-white/[0.06] bg-[#0A0F0C] lg:block">{sidebar}</aside>{open&&<div className="fixed inset-0 z-50 lg:hidden"><div className="absolute inset-0 bg-black/70" onClick={()=>setOpen(false)}/><aside className="absolute inset-y-0 left-0 w-64 bg-[#0A0F0C]">{sidebar}</aside></div>}<div className="lg:pl-64"><header className="sticky top-0 z-30 flex h-16 items-center justify-between border-b border-white/[0.06] bg-[#050807]/90 px-4 backdrop-blur sm:px-6"><button className="rounded-md p-2 hover:bg-white/5 lg:hidden" onClick={()=>setOpen(!open)} aria-label="Toggle navigation">{open?<X className="h-5 w-5"/>:<Menu className="h-5 w-5"/>}</button><p className="hidden text-sm text-zinc-400 sm:block">Research → Project → Resume → Portfolio → Growth</p><Link href="/app/workspaces" className="text-sm font-medium text-indigo-300 hover:text-indigo-200">New workspace</Link></header><main className="mx-auto w-full max-w-7xl px-4 py-6 sm:px-6 lg:px-8">{children}</main></div></div>;}
